mapper.select:
SELECT id, name, price, stock_quantity, image_url, description, active
FROM products
WHERE id = #{id}

SELECT id, name, price, stock_quantity, image_url, description, active FROM products
ORDER BY price ASC, id DESC ORDER BY price DESC, id DESC ORDER BY name ASC, id DESC ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

