UPDATE products
name = #{name}, price = #{price}, image_url = #{imageUrl}, description = #{description}, active = #{active},
WHERE id = #{id}

UPDATE products
SET stock_quantity = #{quantity}
WHERE id = #{productId}
  AND stock_quantity = #{expectedQuantity}

UPDATE products
SET stock_quantity = stock_quantity - #{quantity}
WHERE id = #{productId}
  AND active = TRUE
  AND stock_quantity >= #{quantity}

UPDATE products
SET stock_quantity = stock_quantity + #{quantity}
WHERE id = #{productId}
